#!/usr/bin/env bash
# Receipts for chapter 21 (Node.js / io.js — fork, rename, convergence).
cd "$(dirname "$0")/.."
out=chapters/21-iojs.receipts.md
export LC_ALL=C
g() { desc=$1; cmd=$2; cap=$3; echo '```'; echo "$ $desc"; eval "$cmd" 2>&1 | head -n "$cap"; echo '```'; echo; }
{
echo "# Receipts — ch. 21 Node.js / io.js (fork, rename, convergence)"
echo
echo "Verbatim outputs against the full nodejs/node clone in \`repos/node\`."
echo "Regenerate with \`scripts/receipts-21.sh\`. Outputs are pinned to explicit objects or refs; long outputs are truncated editorially with \`sed\` or \`head\`."
echo
echo "## R1 — a stale remote ref alone retains sixteen commits from the private rehearsal"
g "git -C repos/node branch -r --list '*archived-io.js*'; git -C repos/node for-each-ref refs/remotes/origin/archived-io.js-v0.10 --format='%(objectname) %(refname)'; git -C repos/node branch -r --contains e7dec60a63b9171465fd4037a04aeb709198aea2; printf 'unique_to_archived '; git -C repos/node rev-list --count origin/archived-io.js-v0.10 --not origin/main" "git -C repos/node branch -r --list '*archived-io.js*'; git -C repos/node for-each-ref refs/remotes/origin/archived-io.js-v0.10 --format='%(objectname) %(refname)'; git -C repos/node branch -r --contains e7dec60a63b9171465fd4037a04aeb709198aea2; printf 'unique_to_archived '; git -C repos/node rev-list --count origin/archived-io.js-v0.10 --not origin/main" 8
g "git -C repos/node log --reverse --no-mailmap --format='%H %aI %an <%ae> | %s' origin/archived-io.js-v0.10 --not origin/main -- CONTRIBUTING.md doc/tc-meetings" "git -C repos/node log --reverse --no-mailmap --format='%H %aI %an <%ae> | %s' origin/archived-io.js-v0.10 --not origin/main -- CONTRIBUTING.md doc/tc-meetings" 10
echo "## R2 — 2014-10-01: the stranded branch drafts governance for node-forward/node"
g "git -C repos/node show -s --no-mailmap --format='%H%nparents %P%nAuthor: %aI %an <%ae>%nCommitter: %cI %cn <%ce>%n%n%B' f60abb0ced54f5ba08d324e62ad3fbb306ba37f7" "git -C repos/node show -s --no-mailmap --format='%H%nparents %P%nAuthor: %aI %an <%ae>%nCommitter: %cI %cn <%ce>%n%n%B' f60abb0ced54f5ba08d324e62ad3fbb306ba37f7" 12
g "git -C repos/node show --format='' --no-ext-diff f60abb0ced54f5ba08d324e62ad3fbb306ba37f7 -- CONTRIBUTING.md | sed -n '1,90p'" "git -C repos/node show --format='' --no-ext-diff f60abb0ced54f5ba08d324e62ad3fbb306ba37f7 -- CONTRIBUTING.md | sed -n '1,90p'" 91
echo "## R3 — 2014-10-29: private minutes put a date and the words soft fork on the plan"
g "git -C repos/node show -s --no-mailmap --format='%H%nparents %P%nAuthor: %aI %an <%ae>%nCommitter: %cI %cn <%ce>%n%n%B' e7dec60a63b9171465fd4037a04aeb709198aea2" "git -C repos/node show -s --no-mailmap --format='%H%nparents %P%nAuthor: %aI %an <%ae>%nCommitter: %cI %cn <%ce>%n%n%B' e7dec60a63b9171465fd4037a04aeb709198aea2" 9
g "git -C repos/node show --format='' --no-ext-diff e7dec60a63b9171465fd4037a04aeb709198aea2 -- doc/tc-meetings/2014-10-29.md" "git -C repos/node show --format='' --no-ext-diff e7dec60a63b9171465fd4037a04aeb709198aea2 -- doc/tc-meetings/2014-10-29.md" 18
g "git -C repos/node show e7dec60a63b9171465fd4037a04aeb709198aea2:doc/tc-meetings/2014-10-29.md | sed -n '13,24p'" "git -C repos/node show e7dec60a63b9171465fd4037a04aeb709198aea2:doc/tc-meetings/2014-10-29.md | sed -n '13,24p'" 13
echo "## R4 — 2014-12-01: the public README says exactly what this repository became"
g "git -C repos/node show --no-mailmap --no-ext-diff --format='commit %H%nparents %P%nAuthor: %aI %an <%ae>%nCommitter: %cI %cn <%ce>%n%n%B' 51514c8e8cbd98be7f29c3f1508b625d16e91b5d -- README.md" "git -C repos/node show --no-mailmap --no-ext-diff --format='commit %H%nparents %P%nAuthor: %aI %an <%ae>%nCommitter: %cI %cn <%ce>%n%n%B' 51514c8e8cbd98be7f29c3f1508b625d16e91b5d -- README.md" 42
echo "## R5 — 2015-01-08: the build target and installed executable change from node to iojs"
g "git -C repos/node show -s --no-mailmap --format='%H%nparents %P%nAuthor: %aI %an <%ae>%nCommitter: %cI %cn <%ce>%n%n%B' f17f473af5e28f4ec00a518f97a84b69c426309e" "git -C repos/node show -s --no-mailmap --format='%H%nparents %P%nAuthor: %aI %an <%ae>%nCommitter: %cI %cn <%ce>%n%n%B' f17f473af5e28f4ec00a518f97a84b69c426309e" 22
g "git -C repos/node diff --no-ext-diff f17f473af5e28f4ec00a518f97a84b69c426309e^ f17f473af5e28f4ec00a518f97a84b69c426309e -- node.gyp tools/install.py | sed -n '1,60p'" "git -C repos/node diff --no-ext-diff f17f473af5e28f4ec00a518f97a84b69c426309e^ f17f473af5e28f4ec00a518f97a84b69c426309e -- node.gyp tools/install.py | sed -n '1,60p'" 61
echo "## R6 — 2015-08-13: convergence renames the target and installed executable back to node"
g "git -C repos/node show --no-mailmap --shortstat --format='%H%nparents %P%nAuthor: %aI %an <%ae>%nCommitter: %cI %cn <%ce>%n%n%B' a69ab27ab458385d24676792b75ad1c25b8c30e5" "git -C repos/node show --no-mailmap --shortstat --format='%H%nparents %P%nAuthor: %aI %an <%ae>%nCommitter: %cI %cn <%ce>%n%n%B' a69ab27ab458385d24676792b75ad1c25b8c30e5" 18
g "git -C repos/node diff --no-ext-diff a69ab27ab458385d24676792b75ad1c25b8c30e5^ a69ab27ab458385d24676792b75ad1c25b8c30e5 -- node.gyp tools/install.py | sed -n '1,76p'" "git -C repos/node diff --no-ext-diff a69ab27ab458385d24676792b75ad1c25b8c30e5^ a69ab27ab458385d24676792b75ad1c25b8c30e5 -- node.gyp tools/install.py | sed -n '1,76p'" 77
echo "## R7 — the v4 line imports the v3.3.0 release record as a separate commit"
g "git -C repos/node show -s --no-mailmap --format='%H%nparents %P%nAuthor: %aI %an <%ae>%nCommitter: %cI %cn <%ce>%n%n%B' 8a9a3bf798a3d6dda5a852a01820422c53eea765 | sed -n '1,28p'" "git -C repos/node show -s --no-mailmap --format='%H%nparents %P%nAuthor: %aI %an <%ae>%nCommitter: %cI %cn <%ce>%n%n%B' 8a9a3bf798a3d6dda5a852a01820422c53eea765 | sed -n '1,28p'" 29
g "git -C repos/node merge-base --is-ancestor 8a9a3bf798a3d6dda5a852a01820422c53eea765 'v4.0.0^{}' && echo 'v3.3.0_changelog_import_ancestor_of_v4.0.0=yes'" "git -C repos/node merge-base --is-ancestor 8a9a3bf798a3d6dda5a852a01820422c53eea765 'v4.0.0^{}' && echo 'v3.3.0_changelog_import_ancestor_of_v4.0.0=yes'" 2
echo "## R8 — annotated tags identify the two releases and their distinct commit parents"
g "for tag in v3.3.0 v4.0.0; do git -C repos/node for-each-ref --format='%(refname:short) tag-object=%(objectname) target=%(*objectname) | %(taggerdate:iso8601-strict) %(taggername) <%(taggeremail:trim)> | %(subject)' \"refs/tags/\$tag\"; git -C repos/node show -s --no-mailmap --format='commit %H%nparent %P%nAuthor: %aI %an <%ae>%nCommitter: %cI %cn <%ce>%n%s' \"\$tag^{}\"; done" "for tag in v3.3.0 v4.0.0; do git -C repos/node for-each-ref --format='%(refname:short) tag-object=%(objectname) target=%(*objectname) | %(taggerdate:iso8601-strict) %(taggername) <%(taggeremail:trim)> | %(subject)' \"refs/tags/\$tag\"; git -C repos/node show -s --no-mailmap --format='commit %H%nparent %P%nAuthor: %aI %an <%ae>%nCommitter: %cI %cn <%ce>%n%s' \"\$tag^{}\"; done" 16
echo "## R9 — v3.3.0 is the written baseline, not a Git parent or ancestor of v4.0.0"
g "printf 'v3.3.0_tagged_commit '; git -C repos/node rev-parse 'v3.3.0^{}'; printf 'v4.0.0_tagged_commit '; git -C repos/node rev-parse 'v4.0.0^{}'; printf 'v4.0.0_direct_parent '; git -C repos/node rev-parse 'v4.0.0^'; printf 'merge_base '; git -C repos/node merge-base 'v3.3.0^{}' 'v4.0.0^{}'; printf 'v3_only v4_only '; git -C repos/node rev-list --left-right --count 'v3.3.0^{}...v4.0.0^{}'; if git -C repos/node merge-base --is-ancestor 'v3.3.0^{}' 'v4.0.0^{}'; then echo 'v3.3.0_ancestor_of_v4.0.0=yes'; else echo 'v3.3.0_ancestor_of_v4.0.0=no'; fi" "printf 'v3.3.0_tagged_commit '; git -C repos/node rev-parse 'v3.3.0^{}'; printf 'v4.0.0_tagged_commit '; git -C repos/node rev-parse 'v4.0.0^{}'; printf 'v4.0.0_direct_parent '; git -C repos/node rev-parse 'v4.0.0^'; printf 'merge_base '; git -C repos/node merge-base 'v3.3.0^{}' 'v4.0.0^{}'; printf 'v3_only v4_only '; git -C repos/node rev-list --left-right --count 'v3.3.0^{}...v4.0.0^{}'; if git -C repos/node merge-base --is-ancestor 'v3.3.0^{}' 'v4.0.0^{}'; then echo 'v3.3.0_ancestor_of_v4.0.0=yes'; else echo 'v3.3.0_ancestor_of_v4.0.0=no'; fi" 8
echo "## R10 — the files at the tags change title from io.js to Node.js and name v3.3.0 as v4's baseline"
g "git -C repos/node show 'v3.3.0^{}:CHANGELOG.md' | sed -n '1,8p'" "git -C repos/node show 'v3.3.0^{}:CHANGELOG.md' | sed -n '1,8p'" 9
g "git -C repos/node show 'v4.0.0^{}:CHANGELOG.md' | sed -n '1,14p'" "git -C repos/node show 'v4.0.0^{}:CHANGELOG.md' | sed -n '1,14p'" 15
} > "$out"
echo "wrote $out ($(wc -l < "$out") lines)"
